create or replace function public.route_lsv_candidate(start_lon double precision,start_lat double precision,end_lon double precision,end_lat double precision,allow_unknown boolean default true,snap_max_distance_meters double precision default 500) returns table(path_seq integer,edge_id bigint,edge_name text,edge_status text,maxspeed_mph numeric,length_m double precision,geom_geojson jsonb) set search_path='public, extensions' language plpgsql stable as $$ declare start_node bigint; end_node bigint; graph_sql text; begin graph_sql:=case when allow_unknown then $g$select id,source_node_id source,target_node_id target,length_m cost,-1::double precision reverse_cost from public.road_edges where lsv_status in ('verified_eligible','unknown') and (maxspeed_mph is null or maxspeed_mph<=35)$g$ else $g$select id,source_node_id source,target_node_id target,length_m cost,-1::double precision reverse_cost from public.road_edges where lsv_status='verified_eligible' and (maxspeed_mph is null or maxspeed_mph<=35)$g$ end;
with sc as (select n.id,n.lsv_component,extensions.st_distance(n.geom::extensions.geography,extensions.st_setsrid(extensions.st_point(start_lon,start_lat),4326)::extensions.geography) d from public.road_nodes n where n.lsv_component is not null and extensions.st_dwithin(n.geom::extensions.geography,extensions.st_setsrid(extensions.st_point(start_lon,start_lat),4326)::extensions.geography,snap_max_distance_meters) order by n.geom operator(extensions.<->) extensions.st_setsrid(extensions.st_point(start_lon,start_lat),4326) limit 48), ec as (select n.id,n.lsv_component,extensions.st_distance(n.geom::extensions.geography,extensions.st_setsrid(extensions.st_point(end_lon,end_lat),4326)::extensions.geography) d from public.road_nodes n where n.lsv_component is not null and extensions.st_dwithin(n.geom::extensions.geography,extensions.st_setsrid(extensions.st_point(end_lon,end_lat),4326)::extensions.geography,snap_max_distance_meters) order by n.geom operator(extensions.<->) extensions.st_setsrid(extensions.st_point(end_lon,end_lat),4326) limit 48), direct as (select s.id sid,e.id eid,s.d+e.d score from sc s join ec e on e.lsv_component=s.lsv_component order by score limit 1) select sid,eid into start_node,end_node from direct;
if start_node is null then select n.id into start_node from public.road_nodes n where n.lsv_component is not null and extensions.st_dwithin(n.geom::extensions.geography,extensions.st_setsrid(extensions.st_point(start_lon,start_lat),4326)::extensions.geography,snap_max_distance_meters) order by (case when n.lsv_component=(select lsv_component from public.road_nodes where id=end_node) then 0 else 1 end), n.geom operator(extensions.<->) extensions.st_setsrid(extensions.st_point(start_lon,start_lat),4326) limit 1; end if;
if end_node is null then select n.id into end_node from public.road_nodes n where n.lsv_component is not null and extensions.st_dwithin(n.geom::extensions.geography,extensions.st_setsrid(extensions.st_point(end_lon,end_lat),4326)::extensions.geography,3000) order by n.geom operator(extensions.<->) extensions.st_setsrid(extensions.st_point(end_lon,end_lat),4326) limit 1; end if;
if start_node is null or end_node is null then return; end if;
return query select p.path_seq::integer,e.id,e.name,e.lsv_status,e.maxspeed_mph,e.length_m,extensions.st_asgeojson(e.geom)::jsonb from extensions.pgr_dijkstra(graph_sql,start_node,end_node,true) p join public.road_edges e on e.id=p.edge where p.edge<>-1 order by p.path_seq; end; $$;
